// actualPlayerMode is not resolved until the player exists, so a scoreLoaded read reports
// Disabled on a first load and the OUTGOING player on a swap. playerReady is the first moment
// the answer is true, and it re-fires on every swap and midi load.
useAlphaTabEvent(api, 'playerReady', readPlayer);

